fields.contract:
// All four are in namespace ArgentSea, derive from System.ApplicationException, and signal a defect in a model's mapping declarations or a query/model cardinality mismatch. None is transient: retrying the same call with the same model type and query fails the same way, so callers should treat them as programming/configuration errors (fix the model or the query), not as retryable data errors. Because mapping delegates are compiled lazily and cached per model type, the declaration errors (InvalidMapType, MapAttributeMissing, MultipleMapAttributes) surface on the FIRST use of a model type in a given mapping direction, not at startup.

public sealed class InvalidMapTypeException : ApplicationException {
  InvalidMapTypeException();
  InvalidMapTypeException(string message);
  InvalidMapTypeException(string message, Exception innerException);
  InvalidMapTypeException(PropertyInfo property, int sqlType);                       // "Sql type mismatch: Class {DeclaringType} cannot map property “{Name}” of type “{PropertyType}” to database type enumeration with numeric value of {sqlType}."
  InvalidMapTypeException(string variableName, Type type, int sqlType);             // "... {variableName} cannot be mapped because type {type} does not map to database type enumeration with numeric value of {sqlType}."
  InvalidMapTypeException(string variableName, Type type, int sqlType, string sqlTypeName); // "Sql type mismatch: {variableName} cannot be mapped because type {type} does not map to database type {sqlTypeName} ({sqlType})."
  InvalidMapTypeException(PropertyInfo property, int sqlType, string sqlTypeName);  // "Sql type mismatch: Class {DeclaringType} cannot map property “{Name}” of type “{PropertyType}” to database type {sqlTypeName} ({sqlType})."
  //   both property forms enclose the property name and the property type each in a matched pair of curly quotes (“ ”).
  string VariableName { get; }   // property.Name or the supplied variableName; null for the three message-only constructors
  Type   VariableType { get; }   // property.PropertyType or the supplied type; null for the message-only constructors
  int    SqlType { get; }        // the provider's numeric db-type enumeration value (e.g. SqlDbType / NpgsqlDbType as int); 0 for the message-only constructors
}

public class MapAttributeMissingException : ApplicationException {   // NOT sealed, unlike its siblings
  public enum ShardElement { ShardId, RecordId, ChildId, GrandChildId, GreatGrandChildId }
  MapAttributeMissingException();                    // "No mapping attributes could be found on the model class provided to the mapper."
  MapAttributeMissingException(string message);
  MapAttributeMissingException(string message, Exception innerException);
  MapAttributeMissingException(ShardElement element, string attributeName); // message chosen by element, see the Model Mapping behavior for ShardElement message selection
  ShardElement Element { get; }      // default(ShardElement) == ShardId for the non-element constructors
  string AttributeName { get; }      // the shard-key attribute's declared name that was not found; null for the non-element constructors
}

public sealed class MultipleMapAttributesException : ApplicationException {   // declared in MultipleAttributeException.cs
  MultipleMapAttributesException();                  // "Multiple mapping attributes were found on the same property."
  MultipleMapAttributesException(string message);
  MultipleMapAttributesException(string message, Exception innerException);
  MultipleMapAttributesException(PropertyInfo property); // "Multiple data mapping attributes found. Class {DeclaringType} cannot map property {Name} to multiple database parameters. If this is required, you must explicitly code data property assignments."
  PropertyInfo Property { get; }     // null for the message-only constructors
}

public sealed class UnexpectedMultiRowResultException : ApplicationException {
  UnexpectedMultiRowResultException();                         // "The database returned multiple records when only one was expected."
  UnexpectedMultiRowResultException(string procedureName);     // "Procedure {procedureName} returned multiple records when only one was expected." -- the single-string constructor takes a PROCEDURE NAME, not a message (the message-only constructor is commented out)
  UnexpectedMultiRowResultException(string message, Exception innerException);
}
// The library's only live throw site uses the parameterless constructor, so the message a caller sees never names the query.
